const migrations = migrationInputs.map(input => ({
	...input,
	keyPaths: [...new Set(input.references.map(([keyPath]) => keyPath))],
	references: input.references.map(([keyPath, script, start, end, original]) => {
		const localKey = keyPath.split('.').at(-1)!;
		return {
			keyPath, script, start, end,
			source: original ?? `i18n.ts.${keyPath}`,
			replacement: `$locale${script ? '.value' : ''}.sfc${localKey === '2fa' ? '[\'2fa\']' : `.${localKey}`}`,
		};
	}),
}));

function getLocaleValue(language: string, keyPath: string): string {
	const value = keyPath.split('.').reduce<unknown>((current, key) => (current as Record<string, unknown>)[key], locales[language]);
	if (typeof value !== 'string') throw new Error(`Expected raw label at ${language}:${keyPath}`);
	return value;
}

function getBlocks(file: string): Map<string, Record<string, string>> {
	const { descriptor, errors } = parse(restorePilotHistoricalSource(file, restoreEmailHistoricalSource(file, restoreFinalOwnerHistoricalSource(file, readFileSync(resolve(repoRoot, file), 'utf8')))), { filename: file });
	expect(errors).toEqual([]);
	const blocks = descriptor.customBlocks.filter(block => block.type === 'locale');
	const result = new Map<string, Record<string, string>>();
	for (const block of blocks) {
		expect(block.attrs.lang).toBe('json');
		expect(result.has(String(block.attrs.locale))).toBe(false);
		result.set(String(block.attrs.locale), JSON.parse(block.content) as Record<string, string>);
	}
	return result;
}

const compiledSources = new Map<string, string>();

async function compileSource(file: string): Promise<string> {
	const cached = compiledSources.get(file);
	if (cached) return cached;
	const filename = resolve(repoRoot, file);
	const source = readFileSync(filename, 'utf8');
	const plugin = pluginVvi();
	const configure = plugin.configResolved;
	const transform = plugin.transform;
	if (typeof configure !== 'function' || !transform || typeof transform === 'function') throw new Error('Expected VVI hooks');
	configure.call({} as never, { root: resolve(repoRoot, 'packages/frontend'), command: 'serve', base: '/', build: { ssr: false } } as never);
	const transformed = await transform.handler.call({} as never, source, filename);
	const transformedSource = typeof transformed === 'string' ? transformed : transformed?.code?.toString() ?? source;
	expect(transformedSource).not.toContain('<locale locale=');
	const { descriptor, errors } = parse(transformedSource, { filename });
	expect(errors).toEqual([]);
	const compiled = compileScript(descriptor, { id: file, inlineTemplate: true });
	const output = ts.transpileModule(compiled.content, {
		compilerOptions: { module: ts.ModuleKind.CommonJS, target: ts.ScriptTarget.ES2022 },
		reportDiagnostics: true,
	});
	expect(output.diagnostics).toEqual([]);
	compiledSources.set(file, output.outputText);
	return output.outputText;
}

async function compileComponent(file: string, dependencies: Record<string, unknown>): Promise<Component> {
	const exports: { default?: Component } = {};
	runInNewContext(await compileSource(file), {
		exports,
		require(specifier: string) {
			if (specifier === 'vue') return Vue;
			if (specifier === 'virtual:vite-vue-internationalization') return VviRuntime;
			if (Object.hasOwn(dependencies, specifier)) return { __esModule: true, ...(dependencies[specifier] as Record<string, unknown>) };
			throw new Error(`Unexpected dependency: ${specifier}`);
		},
		window, document: window.document, navigator, console,
	}, { filename: file });
	if (!exports.default) throw new Error(`Missing compiled component: ${file}`);
	return exports.default;
}

function replacementOccurrences(source: string, replacement: string): number {
	const escaped = replacement.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
	return [...source.matchAll(new RegExp(`${escaped}(?![\\w$])`, 'g'))].length;
}

async function loadActualLocale(language: string) {
	const runtime = createInternationalization({ initialLocale: language });
	await runtime.ready;
	await runtime.loadLocale(language);
	return runtime;
}

describe('next74 static raw-label ownership', () => {
	test('keeps the frozen mechanical boundary', () => {
		expect(migrations).toHaveLength(74);
		expect(migrations.reduce((sum, input) => sum + input.references.length, 0)).toBe(1423);
		expect(migrations.reduce((sum, input) => sum + input.keyPaths.length, 0)).toBe(1109);
		expect(languages).toHaveLength(28);
	});

	test.each(migrations)('$file preserves all languages and reconstructs the original complete source', async migration => {
		const source = restoreRssContractBaseline(migration.file, restorePilotHistoricalSource(migration.file, restoreEmailHistoricalSource(migration.file, restoreFinalOwnerHistoricalSource(migration.file, restoreProductNameBaseline(migration.file, readFileSync(resolve(repoRoot, migration.file), 'utf8'))))));
		const blocks = getBlocks(migration.file);
		expect([...blocks.keys()]).toEqual([...languages]);
		expect(source).not.toContain(legacyImport);
		const unique = [...new Map(migration.references.map(reference => [reference.replacement, reference])).values()];
		for (const reference of unique) {
			expect(replacementOccurrences(source, reference.replacement)).toBe(migration.references.filter(item => item.replacement === reference.replacement).length);
		}
		for (const language of languages) {
			const dictionary = blocks.get(language)!;
			expect(Object.keys(dictionary)).toEqual(migration.keyPaths.map(key => key.split('.').at(-1)!));
			for (const keyPath of migration.keyPaths) {
				const actual = dictionary[keyPath.split('.').at(-1)!];
				const expected = getLocaleValue(language, keyPath);
				expect(actual).toBe(expected);
				expect(Buffer.from(actual, 'utf8')).toEqual(Buffer.from(expected, 'utf8'));
				expect(expected).not.toMatch(/\{\w+\}/);
			}
		}

		const localeStart = source.indexOf('<locale locale=');
		expect(source.slice(localeStart - migration.localeSeparatorNewlines, localeStart)).toBe('\n'.repeat(migration.localeSeparatorNewlines));
		let reversed = source.slice(0, localeStart - migration.localeSeparatorNewlines);
		const importSource = legacyImport + '\n'.repeat(migration.importExtraNewlines ?? 0);
		const edits = [
			...(migration.extraEdits ?? []),
			...migration.references,
			{ start: migration.importOffset, end: migration.importOffset + importSource.length, source: importSource, replacement: '' },
		].sort((a, b) => a.start - b.start);
		let delta = 0;
		const reversal = edits.map(edit => {
			const nextStart = edit.start + delta;
			delta += edit.replacement.length - (edit.end - edit.start);
			return { ...edit, nextStart, nextEnd: nextStart + edit.replacement.length };
		});
		for (const edit of reversal.reverse()) {
			expect(reversed.slice(edit.nextStart, edit.nextEnd)).toBe(edit.replacement);
			reversed = reversed.slice(0, edit.nextStart) + edit.source + reversed.slice(edit.nextEnd);
		}
		expect(createHash('sha256').update(reversed).digest('hex')).toBe(migration.sha256);
		// The real repository wrapper, installed VVI transform and Vue compiler
		// must accept the unchanged template/script/styles and static numeric key.
		expect(await compileSource(migration.file)).toContain('virtual:vite-vue-internationalization');
	});

	test.each(languages)('actual VVI plugin loaders resolve all 74 raw dictionaries in %s', async language => {
		const runtime = await loadActualLocale(language);
		Vue.createApp({}).use(runtime);
		for (const migration of migrations) {
			const dictionary = VviRuntime.createComponentLocale('/' + migration.file.replace(/^packages\//, ''));
			for (const keyPath of migration.keyPaths) {
				const actual = dictionary[keyPath.split('.').at(-1)!];
				const expected = reviewedFinalOwnerMessage(migration.file, language, keyPath.split('.').at(-1)!, reviewedEmailMessage(migration.file, language, keyPath.split('.').at(-1)!, reviewedPilotMessage(migration.file, language, keyPath.split('.').at(-1)!, getLocaleValue(language, keyPath))));
				expect(actual).toBe(expected);
				expect(Buffer.from(String(actual), 'utf8')).toEqual(Buffer.from(expected, 'utf8'));
			}
		}
	});

	test.each(languages)('actual compiled TOTP view retains static bracket labels, toggle and latest submission in %s', async language => {
		const file = 'packages/features/auth/frontend/components/MkSignin.totp.vue';
		const input = Vue.defineComponent({
			props: ['modelValue', 'pattern', 'inputmode'],
			emits: ['update:modelValue'],
			setup: (props, { emit, slots }) => () => Vue.h('label', [
				slots.label?.(),
				Vue.h('input', { value: props.modelValue, pattern: props.pattern, inputmode: props.inputmode, onInput: (event: Event) => emit('update:modelValue', (event.target as HTMLInputElement).value) }),
				slots.caption?.(),
			]),
		});
		const button = Vue.defineComponent({ setup: (_props, { slots }) => () => Vue.h('button', slots.default?.()) });
		const component = await compileComponent(file, {
			'@features/ui/frontend/components/MkInput.vue': { default: input },
			'@features/ui/frontend/components/MkButton.vue': { default: button },
		});
		const submitted: string[] = [];
		const app = Vue.createApp(component, { onTotpSubmitted: (token: string) => submitted.push(token) });
		app.use(await loadActualLocale(language));
		app.config.globalProperties.$style = new Proxy({}, { get: (_target, key) => String(key) });
		const element = window.document.createElement('div');
		app.mount(element);
		try {
			expect(element.querySelector('.totpDescription')?.textContent).toBe(locales[language]['2fa']);
			const field = element.querySelector('input')!;
			const toggle = element.querySelector<HTMLButtonElement>('._textButton')!;
			expect(field.getAttribute('pattern')).toBe('^[0-9]{6}$');
			expect(toggle.textContent).toBe(locales[language].useBackupCode);
			toggle.click();
			await Vue.nextTick();
			expect(field.getAttribute('pattern')).toBe('^[A-Z0-9]{32}$');
			expect(toggle.textContent).toBe(locales[language].useTotp);
			field.value = 'A'.repeat(32);
			field.dispatchEvent(new Event('input', { bubbles: true }));
			await Vue.nextTick();
			element.querySelector('form')!.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
			expect(submitted).toEqual(['A'.repeat(32)]);
			toggle.click();
			await Vue.nextTick();
			expect(field.getAttribute('pattern')).toBe('^[0-9]{6}$');
			field.value = '654321';
			field.dispatchEvent(new Event('input', { bubbles: true }));
			await Vue.nextTick();
			element.querySelector('form')!.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
			expect(submitted).toEqual(['A'.repeat(32), '654321']);
		} finally {
			app.unmount();
		}
	});
});
